// Basic types
let name: string = "TypeScript";
let version: number = 5.4;
let isAwesome: boolean = true;
let skills: string[] = ["React", "Node"];

// Interface: define object shape
interface User {
  id: number;
  name: string;
  email: string;
  age?: number;           // optional
  readonly createdAt: Date; // immutable
}

// Type alias
type Status = "active" | "inactive" | "banned"; // union
type Point = { x: number; y: number };

// Function with types
function greet(user: User): string {
  return `Hello ${user.name}!`;
}

// Array methods are type-safe
const activeUsers = users.filter(
  (u): u is User => u.status === "active" // type guard
);

// Generic function
function first<T>(arr: T[]): T | undefined {
  return arr[0];
}
const num = first([1, 2, 3]);      // number | undefined
const str = first(["a", "b"]);     // string | undefined

// Generic interface
interface ApiResponse<T> {
  data: T;
  status: number;
  message: string;
}

async function fetchUsers(): Promise<ApiResponse<User[]>> {
  const res = await fetch("/api/users");
  return res.json();
}

// Utility types
type CreateUser = Omit<User, "id" | "createdAt">;
type UpdateUser = Partial<CreateUser>;
type UserPreview = Pick<User, "id" | "name">;

// Discriminated union (type-safe state)
type RequestState<T> =
  | { status: "idle" }
  | { status: "loading" }
  | { status: "success"; data: T }
  | { status: "error"; error: string };

function renderState(state: RequestState<User[]>) {
  switch (state.status) {
    case "loading": return "Loading...";
    case "success": return state.data.map(u => u.name); // TS knows data exists!
    case "error": return state.error; // TS knows error exists!
  }
}

// Mapped types: transform object types
type Readonly<T> = { readonly [K in keyof T]: T[K] };
type Nullable<T> = { [K in keyof T]: T[K] | null };

// Conditional types
type IsString<T> = T extends string ? true : false;
type A = IsString<"hello">; // true
type B = IsString<42>;      // false

// Template literal types
type HttpMethod = "GET" | "POST" | "PUT" | "DELETE";
type ApiEndpoint = `/api/${string}`;
type Route = `${HttpMethod} ${ApiEndpoint}`;
// Route = "GET /api/..." | "POST /api/..." | ...

// Branded types for domain safety
type USD = number & { __brand: "USD" };
type EUR = number & { __brand: "EUR" };

function usd(amount: number): USD { return amount as USD; }
function eur(amount: number): EUR { return amount as EUR; }

function addUSD(a: USD, b: USD): USD { return (a + b) as USD; }
// addUSD(usd(10), eur(20)); // ERROR! Can't mix USD and EUR

// satisfies operator (TS 5+)
const config = {
  port: 3000,
  host: "localhost",
  debug: true
} satisfies Record<string, string | number | boolean>;
// config.port is still `number` (not string | number | boolean)

// Type-safe builder pattern
type Builder<T extends Record<string, any>> = {
  set<K extends string, V>(key: K, value: V): Builder<T & Record<K, V>>;
  build(): T;
};

function createBuilder(): Builder<{}> {
  const obj: any = {};
  return {
    set(key, value) {
      obj[key] = value;
      return this as any;
    },
    build() { return obj; }
  };
}

const result = createBuilder()
  .set("name", "TypeScript")
  .set("version", 5.4)
  .set("released", true)
  .build();
// result type: { name: string; version: number; released: boolean }

// Recursive type: deep partial
type DeepPartial<T> = T extends object
  ? { [K in keyof T]?: DeepPartial<T[K]> }
  : T;

// Extract route params from string
type ExtractParams<T extends string> =
  T extends `${string}:${infer Param}/${infer Rest}`
    ? Param | ExtractParams<Rest>
    : T extends `${string}:${infer Param}`
      ? Param
      : never;

type Params = ExtractParams<"/users/:id/posts/:postId">;
// Params = "id" | "postId"

// Custom type transformer using ts-morph
import { Project, SyntaxKind } from "ts-morph";

const project = new Project();
const sourceFile = project.addSourceFileAtPath("./src/types.ts");

// Find all interfaces
const interfaces = sourceFile.getInterfaces();

for (const iface of interfaces) {
  console.log(`Interface: ${iface.getName()}`);

  // Generate runtime validator from type
  const properties = iface.getProperties();
  const validators = properties.map(prop => {
    const name = prop.getName();
    const type = prop.getType().getText();
    const optional = prop.hasQuestionToken();
    return { name, type, optional };
  });

  console.log("Validators:", validators);
}

// Declaration merging
declare module "express" {
  interface Request {
    user?: { id: string; role: string };
    requestId: string;
  }
}

// Module augmentation
declare global {
  interface Array<T> {
    groupBy(fn: (item: T) => string): Record<string, T[]>;
  }
}
